  message: string;
  hint?: string;
};

export function EmptyState({ icon, message, hint }: EmptyStateProps) {
  return (
    <div
      role="status"
      className="flex flex-col items-center justify-center gap-3 p-6 rounded-lg border border-zinc-800 bg-zinc-900 text-center"
    >
      <div className="flex h-10 w-10 items-center justify-center rounded-full bg-zinc-800 text-zinc-300">
        {icon ?? (
          <svg
            className="h-5 w-5"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <path d="M20 13V7a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v6" />
            <path d="M4 13v4a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-4" />
            <path d="M4 13h4l2 2h4l2-2h4" />
          </svg>
        )}
      </div>

      <div className="flex flex-col gap-1">
        <p className="text-sm font-medium text-zinc-200">{message}</p>

        {hint ? <p className="text-xs text-zinc-400">{hint}</p> : null}
      </div>
    </div>
  );
}
